package xyz.dvdsgl.tvremote.companion

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Assert.assertThrows
import org.junit.Assert.assertTrue
import org.junit.Test
import xyz.dvdsgl.tvremote.companion.Golden.bytes

/** Checks the Kotlin port byte for byte against vectors generated by pyatv 0.18.0. */
class GoldenTest {
    private val g = Golden.json

    @Test fun opackPacksLikePyatv() {
        for (v in Golden.objects(g.getJSONArray("opack")).filter { it.has("value") }) {
            val packed = Opack.pack(Golden.value(v.getJSONObject("value")))
            assertEquals(v.getString("packed"), packed.hex())
        }
    }

    @Test fun opackUnpacksLikePyatv() {
        for (v in Golden.objects(g.getJSONArray("opack"))) {
            val unpacked = Opack.unpack(bytes(v.getString("packed")))
            Golden.assertSame("unpack ${v.getString("packed").take(40)}", Golden.value(v.getJSONObject("unpacked")), unpacked)
        }
    }

    @Test fun tlv8() {
        val t = g.getJSONObject("tlv")
        val items = t.getJSONArray("items").let { a -> List(a.length()) { a.getJSONArray(it).getInt(0) to bytes(a.getJSONArray(it).getString(1)) } }
        assertEquals(t.getString("written"), Tlv8.write(*items.toTypedArray()).hex())
        val read = Tlv8.read(bytes(t.getString("written")))
        val expected = t.getJSONArray("read")
        assertEquals(expected.length(), read.size)
        for (i in 0 until expected.length()) {
            assertEquals(expected.getJSONArray(i).getString(1), read[expected.getJSONArray(i).getInt(0)]!!.hex())
        }
    }

    @Test fun hkdf() {
        for (v in Golden.objects(g.getJSONObject("primitives").getJSONArray("hkdf"))) {
            assertEquals(v.getString("okm"), Crypto.hkdf(v.getString("salt"), v.getString("info"), bytes(v.getString("ikm"))).hex())
        }
    }

    @Test fun ed25519() {
        for (v in Golden.objects(g.getJSONObject("primitives").getJSONArray("ed25519"))) {
            val seed = bytes(v.getString("seed"))
            val msg = bytes(v.getString("message"))
            val sig = bytes(v.getString("signature"))
            val pub = bytes(v.getString("public"))
            assertEquals(v.getString("public"), Ed25519.publicKey(seed).hex())
            assertEquals(v.getString("signature"), Ed25519.sign(seed, msg).hex())
            assertTrue(Ed25519.verify(pub, msg, sig))
            assertFalse(Ed25519.verify(pub, msg + byteArrayOf(1), sig))
            assertFalse(Ed25519.verify(pub, msg, sig.copyOf().also { it[5] = (it[5] + 1).toByte() }))
        }
    }

    @Test fun x25519() {
        for (v in Golden.objects(g.getJSONObject("primitives").getJSONArray("x25519"))) {
            val priv = bytes(v.getString("private"))
            assertEquals(v.getString("public"), X25519.publicKey(priv).hex())
            assertEquals(v.getString("shared"), X25519.sharedSecret(priv, bytes(v.getString("peerPublic"))).hex())
        }
        assertThrows(IllegalArgumentException::class.java) { X25519.sharedSecret(ByteArray(32) { 1 }, ByteArray(32)) }
    }

    @Test fun chacha20Poly1305() {
        for (v in Golden.objects(g.getJSONObject("primitives").getJSONArray("chacha"))) {
            val key = bytes(v.getString("key"))
            val nonce = bytes(v.getString("nonce"))
            val aad = bytes(v.getString("aad"))
            val sealed = Crypto.seal(key, nonce, bytes(v.getString("plain")), aad)
            assertEquals(v.getString("sealed"), sealed.hex())
            assertEquals(v.getString("plain"), Crypto.open(key, nonce, sealed, aad).hex())
            sealed[0] = (sealed[0] + 1).toByte()
            assertThrows(Exception::class.java) { Crypto.open(key, nonce, sealed, aad) }
        }
    }

    @Test fun srp() {
        val p = g.getJSONObject("pairing")
        val s = p.getJSONObject("srp")
        val srp = Srp(p.getString("pin"), bytes(s.getString("a")))
        assertEquals(s.getString("A"), srp.publicKey.hex())
        srp.process(bytes(s.getString("B")), bytes(s.getString("salt")))
        assertEquals(s.getString("K"), srp.sessionKey.hex())
        assertEquals(s.getString("M"), srp.proof.hex())
        assertEquals(s.getString("serverProof"), srp.expectedServerProof.hex())
    }

    @Test fun pairSetup() {
        val p = g.getJSONObject("pairing")
        val m = p.getJSONObject("setup")
        val setup = PairSetup(bytes(p.getString("setupSeed")), bytes(p.getString("pairingId")))
        assertEquals(m.getString("m1"), setup.m1().hex())
        setup.m2(bytes(m.getString("m2")))
        assertEquals(m.getString("m3"), setup.m3(p.getString("pin")).hex())
        assertEquals(m.getString("m5"), setup.m5(bytes(m.getString("m4")), p.getString("name")).hex())
        assertEquals(p.getString("credentials"), setup.m6(bytes(m.getString("m6"))).toString())
    }

    @Test fun pairSetupWrongPin() {
        val p = g.getJSONObject("pairing")
        val m = p.getJSONObject("setup")
        val setup = PairSetup(bytes(p.getString("setupSeed")), bytes(p.getString("pairingId")))
        setup.m2(bytes(m.getString("m2")))
        setup.m3("9999")
        val e = assertThrows(PairingException::class.java) { setup.m5(bytes(p.getString("wrongPinM4")), "x") }
        assertEquals("Wrong code", e.message)
        // A forged M4 proof (right format, wrong value) is rejected too.
        val forged = PairSetup(bytes(p.getString("setupSeed")), bytes(p.getString("pairingId")))
        forged.m2(bytes(m.getString("m2")))
        forged.m3("9999")
        assertThrows(PairingException::class.java) { forged.m5(bytes(m.getString("m4")), "x") }
    }

    @Test fun pairVerify() {
        val p = g.getJSONObject("pairing")
        val m = p.getJSONObject("verify")
        val creds = Credentials.parse(p.getString("credentials"))
        assertEquals(p.getString("credentials"), creds.toString())
        val verify = PairVerify(creds, bytes(p.getString("verifyPrivate")))
        assertEquals(m.getString("m1"), verify.m1().hex())
        assertEquals(m.getString("m3"), verify.m3(bytes(m.getString("m2"))).hex())
        verify.m4(bytes(m.getString("m4")))
        val (out, inp) = verify.keys()
        assertEquals(p.getString("outputKey"), out.hex())
        assertEquals(p.getString("inputKey"), inp.hex())
    }

    @Test fun pairVerifyRejectsAnotherTv() {
        val p = g.getJSONObject("pairing")
        val m = p.getJSONObject("verify")
        val c = Credentials.parse(p.getString("credentials"))
        val otherId = PairVerify(Credentials(c.ltpk, c.ltsk, "someone else".toByteArray(), c.clientId), bytes(p.getString("verifyPrivate")))
        otherId.m1()
        assertThrows(PairingException::class.java) { otherId.m3(bytes(m.getString("m2"))) }
        val otherKey = PairVerify(Credentials(Ed25519.publicKey(ByteArray(32)), c.ltsk, c.atvId, c.clientId), bytes(p.getString("verifyPrivate")))
        assertThrows(PairingException::class.java) { otherKey.m3(bytes(m.getString("m2"))) }
        assertThrows(PairingException::class.java) { PairVerify(c).m4(Tlv8.write(Tlv8.SEQ_NO to byteArrayOf(4), Tlv8.ERROR to byteArrayOf(2))) }
    }

    @Test fun rtiPayloads() {
        val p = g.getJSONObject("plist")
        val session = bytes(p.getString("session"))
        for (v in Golden.objects(p.getJSONArray("input"))) {
            assertEquals(v.getString("text"), v.getString("payload"), Bplist.rtiInputText(session, v.getString("text")).hex())
        }
        assertEquals(p.getString("clear"), Bplist.rtiClearText(session).hex())
    }

    @Test fun keyedArchive() {
        val p = g.getJSONObject("plist")
        val archive = bytes(p.getString("archive"))
        assertArrayEquals(bytes(p.getString("archiveSession")), Bplist.archiveValue(archive, "sessionUUID") as ByteArray)
        assertEquals(p.getString("archiveText"), Bplist.archiveValue(archive, "documentState", "docSt", "contextBeforeInput"))
        assertNull(Bplist.archiveValue(bytes(p.getString("archiveNoText")), "documentState", "docSt", "contextBeforeInput"))
        // Our own payloads read back through the same path.
        val ours = Bplist.rtiInputText(bytes(p.getString("session")), "héllo")
        assertEquals("héllo", Bplist.archiveValue(ours, "textOperations", "keyboardOutput", "insertionText"))
        assertArrayEquals(bytes(p.getString("session")), Bplist.archiveValue(ours, "textOperations", "targetSessionUUID", "NS.uuidbytes") as ByteArray)
    }
}
